/* ================================================
 * 顶栏 · 原生按钮绝对定位，自由移动位置
 * 头像为变量，所有装饰用伪元素实现
 * ================================================ */

/* ========== 关键修复：扒掉所有原生外层盒子的定位权限 ========== */
.chat-header-content,
.header-left-section,
.header-title-container,
.header-actions,
.header-btn-wrapper,
.header-btn-back-wrapper,
.header-btn-phone-wrapper,
.header-btn-video-wrapper,
.header-btn-info-wrapper,
.header-right-section {
  position: static !important;
  transform: none !important;
  margin: 0 !important;
  padding: 0 !important;
  top: auto !important;
  left: auto !important;
  right: auto !important;
  bottom: auto !important;
  width: auto !important;
  height: auto !important;
  display: block !important;
  background: transparent !important;
  border: none !important;
  pointer-events: none !important; /* 让这些盒子不拦截点击事件 */
}

/* 顶栏容器 - 白色背景，无圆角，相对定位作为参照 */
.chat-header-custom {
  background: #ffffff !important;

  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;

  border-bottom: 1px solid rgba(0, 0, 0, 0.05) !important;
  border-radius: 0 !important;

  /* 保留原有高度宽度尺寸 */
  height: auto !important;
  min-height: 190px !important;
  max-width: 450px !important;
  margin: 0 auto 0 auto !important;
  position: relative !important;
  top: auto !important;
  left: auto !important;
  right: auto !important;
  z-index: 100 !important;
  overflow: visible !important;
  padding: 0 20px !important;
  width: calc(100%) !important;
}

/* ========== 隐藏原生图标，保留按钮功能 ========== */

/* 返回按钮 - 隐藏原生SVG图标 */
.header-btn-back svg {
  display: none !important;
}

/* 电话按钮 - 隐藏原生SVG图标 */
.header-btn-phone svg {
  display: none !important;
}

/* 视频按钮 - 隐藏原生SVG图标 */
.header-btn-video svg {
  display: none !important;
}

/* 设置按钮 - 隐藏原生SVG图标 */
