  display: none !important;
}

/* ========== 原生按钮绝对定位 + 自定义图标 ========== */

/* 返回按钮 - 绝对定位，自由移动 */
.header-btn-back {
  position: absolute !important;
  top: -35px !important;
  left: -25px !important;
  width: 82px !important;
  height: 82px !important;
  background-image: url('https://i.postimg.cc/D0fYnCbj/IMG-1850.png') !important;
  background-size: 50px 50px !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  z-index: 20 !important;
}

/* 电话按钮 - 绝对定位，自由移动 */
.header-btn-phone {
  position: absolute !important;
  top: 40px !important;
  right: 202px !important;
  width: 160px !important;
  height: 70px !important;
  background-image: url('https://i.postimg.cc/05JdL0wt/IMG_1845.png') !important;
  background-size: 170px 52px !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  z-index: 20 !important;
}

/* 视频按钮 - 绝对定位，自由移动 */
.header-btn-video {
  position: absolute !important;
  top: 40px !important;
  right: 37px !important;
  width: 160px !important;
  height: 70px !important;
  background-image: url('https://i.postimg.cc/gc6qfHZg/IMG_1844.png') !important;
  background-size: 170px 52px !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  z-index: 20 !important;
}

/* 设置按钮 - 绝对定位，自由移动 */
.header-btn-info {
  position: absolute !important;
  top: 33px !important;
  right: -28px !important;
  width: 80px !important;
  height: 80px !important;
  background-image: url('https://i.postimg.cc/7PTMpn2p/IMG_1849.png') !important;
  background-size: 37px 37px !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  z-index: 20 !important;
}

/* ========== 头像容器（变量，可移动、可调整大小） ========== */
.header-avatar-container {
  position: absolute !important;
  top: 45px !important;
  left: 25px !important;
  width: 75px !important;
  height: 75px !important;
  border-radius: 50% !important;
  overflow: hidden !important;
  z-index: 20 !important;
}

.header-avatar-container img {
  width: 100% !important;
