/* =========================================
   1. 我方气泡 (User) 样式
========================================= */
.bubble-me-custom {
  background-color: #a483f6 !important;
  color: #ffffff !important;
  padding: 8px 12px !important;

  /* 统一无连续气泡圆角：左上18 右上6 右下18 左下18 */
