* ======================================================= */

/* 1. 定义一个名为 "breathing-glow" 的动画 */
@keyframes breathing-glow {
 /* 动画开始和结束时：一个非常细微、贴近头像的光环 */
 0%, 100% {
   box-shadow: 0 0 6px rgba(255, 255, 255, 0.4);
 }
