:root {
  /* ---- 我方气泡：2A2A2A 黑底白字、方形直角 ---- */
  --bubble-me-bg: #2A2A2A;
  --bubble-me-color: #ffffff;
  --bubble-me-padding: 5.5px 9.5px;
  --bubble-me-font-size: 12.8px;
  --bubble-me-line-height: 1.28;
  --bubble-me-radius: 0;
  --bubble-me-radius-first: 0;
  --bubble-me-radius-mid: 0;
  --bubble-me-radius-last: 0;
  --bubble-me-shadow: none;
  --bubble-me-border: none;

  /* ---- 对方气泡：灰色底黑字、方形直角 ---- */
  --bubble-them-bg: #eeeeee;
  --bubble-them-color: #1a1a1a;
  --bubble-them-padding: 5.5px 9.5px;
  --bubble-them-font-size: 12.8px;
  --bubble-them-line-height: 1.28;
  --bubble-them-radius: 0;
  --bubble-them-radius-first: 0;
  --bubble-them-radius-mid: 0;
  --bubble-them-radius-last: 0;
  --bubble-them-shadow: none;
  --bubble-them-border: none;

  --chat-message-max-width: 64%;
  --bubble-me-link-color: #ffffff;
  --bubble-them-link-color: #0095f6;

  /* ==========================================
     转账卡片 - 底色跟随各自气泡底色 + 整体大幅缩小
     ========================================== */
  --transfer-card-bg: #ffffff;
  --transfer-me-card-bg: var(--bubble-me-bg);
  --transfer-me-card-border: none;
  --transfer-me-card-shadow: none;
  --transfer-them-card-bg: var(--bubble-them-bg);
  --transfer-them-card-border: none;
  --transfer-them-card-shadow: none;
  --transfer-success-card-bg: var(--bubble-me-bg);
  --transfer-rejected-card-bg: var(--bubble-me-bg);
  --transfer-expired-card-bg: var(--bubble-me-bg);
  --transfer-card-radius: 0;          /* 方形直角 */
  --transfer-card-shadow: none;
  --transfer-card-border: none;

  /* 整体缩小：宽度、内容内边距、头部间距、图标、字号 */
  --transfer-card-width: 150px;       /* 卡片宽度大幅收窄，可按需调 */
  --transfer-content-padding: 6px 8px;
  --transfer-header-margin-bottom: 4px;
  --transfer-icon-size: 22px;         /* 图标外框缩小 */
  --transfer-icon-svg-size: 12px;     /* 图标内部 svg 缩小 */
  --transfer-icon-padding: 0;
  --transfer-amount-font-size: 15px;  /* 金额缩小 */
  --transfer-label-font-size: 10px;
  --transfer-subtitle-font-size: 10px;
  --transfer-status-font-size: 10px;
  --transfer-divider-margin: 4px 0;
}

/* ⭐头像旁文字标签(To/By) */

/* ---- 对方头像右侧加 "Pain" ---- */
.msg-avatar-them-container.is-first::after,
.msg-avatar-them-container.is-single::after {
  content: "Pain" !important;
  position: absolute !important;
  left: calc(100% + 6px) !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  font-size: 12px !important;
  color: #999999 !important;
  font-weight: 400 !important;
  white-space: nowrap !important;
  pointer-events: none !important;
}

/* 对方头像容器需要相对定位 */
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  position: relative !important;
}

/* ---- 我方头像左侧加 "Ease" ---- */
.msg-avatar-me-container.is-last::before,
.msg-avatar-me-container.is-single::before {
  content: "Ease" !important;
  position: absolute !important;
  right: calc(100% + 6px) !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  font-size: 12px !important;
  color: #999999 !important;
  font-weight: 400 !important;
  white-space: nowrap !important;
  pointer-events: none !important;
}

/* 我方头像容器需要相对定位 */
.msg-avatar-me-container.is-last,
.msg-avatar-me-container.is-single {
  position: relative !important;
}

/* ==========================================
   🎯 装饰图标 & 无缝边框 (双方统一连体边框)
   ========================================== */

/* ---- 1. 我方气泡基础设置 ---- */
.bubble-me-custom {
  position: relative !important;
  overflow: visible !important;
  /* 方形直角、无边框 */
  border-radius: 0 !important;
  border: none !important;
  box-shadow: none !important;
  filter: none !important;
}
.bubble-me-custom::after {
  content: "";
  position: absolute;
  bottom: -6px;
  right: -3px;
  width: 19.5px;
  height: 19.5px;
  background-color: var(--bubble-me-bg);
  mask: url("https://img.heliar.top/file/1781508626995_retouch_2026061115350112.png") no-repeat center / contain;
  -webkit-mask: url("https://img.heliar.top/file/1781508626995_retouch_2026061115350112.png") no-repeat center / contain;
  transform: rotate(0deg);
  pointer-events: none;
  z-index: 2;
}

/* ---- 2. 对方气泡基础设置 ---- */
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
  /* 方形直角、无边框 */
  border-radius: 0 !important;
  border: none !important;
  box-shadow: none !important;
  filter: none !important;
}
.bubble-them-custom::after {
  content: "";
  position: absolute;
  top: -6px;
  left: -3px;
  width: 19.5px;
  height: 19.5px;
  background-color: var(--bubble-them-bg);
  mask: url("https://img.heliar.top/file/1781508626995_retouch_2026061115350112.png") no-repeat center / contain;
  -webkit-mask: url("https://img.heliar.top/file/1781508626995_retouch_2026061115350112.png") no-repeat center / contain;
  transform: rotate(45deg);
  pointer-events: none;
  z-index: 2;
}

/* ---- 3. 🎯 核心逻辑：侦测系统状态，精准剔除不需要的图标 ---- */

/* 对方：只保留第一条 */
.msg-them.is-mid .bubble-them-custom::after,
.msg-them.is-last .bubble-them-custom::after,
.bubble-them-custom.is-mid::after,
.bubble-them-custom.is-last::after,
.msg-them:has(.is-mid) .bubble-them-custom::after,
.msg-them:has(.is-last) .bubble-them-custom::after {
  display: none !important;
}

/* 我方：只保留最后一条 */
.msg-me.is-first .bubble-me-custom::after,
.msg-me.is-mid .bubble-me-custom::after,
.bubble-me-custom.is-first::after,
.bubble-me-custom.is-mid::after,
.msg-me:has(.is-first) .bubble-me-custom::after,
.msg-me:has(.is-mid) .bubble-me-custom::after {
  display: none !important;
}

/* ==========================================
   特殊消息处理（图片/表情/转账卡片）
   ========================================== */

.msg-me .msg-transfer-card {
  background: var(--bubble-me-bg) !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  /* 整体缩小 */
  width: var(--transfer-card-width) !important;
  max-width: var(--transfer-card-width) !important;
}
.msg-them .msg-transfer-card {
  background: var(--bubble-them-bg) !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  /* 整体缩小 */
  width: var(--transfer-card-width) !important;
  max-width: var(--transfer-card-width) !important;
}

/* 内容区、头部、图标、金额、字号同步缩小 */
.msg-transfer-card .msg-transfer-content,
.msg-transfer-card [class*="transfer-content"] {
  padding: var(--transfer-content-padding) !important;
}
.msg-transfer-card .msg-transfer-header {
  margin-bottom: var(--transfer-header-margin-bottom) !important;
}
.msg-transfer-card .msg-transfer-icon {
  width: var(--transfer-icon-size) !important;
  height: var(--transfer-icon-size) !important;
  padding: var(--transfer-icon-padding) !important;
}
.msg-transfer-card .msg-transfer-icon svg {
  width: var(--transfer-icon-svg-size) !important;
  height: var(--transfer-icon-svg-size) !important;
}
.msg-transfer-card .msg-transfer-amount {
  font-size: var(--transfer-amount-font-size) !important;
}
.msg-transfer-card .msg-transfer-label {
  font-size: var(--transfer-label-font-size) !important;
}
.msg-transfer-card .msg-transfer-subtitle {
  font-size: var(--transfer-subtitle-font-size) !important;
}
.msg-transfer-card .msg-transfer-status-text {
  font-size: var(--transfer-status-font-size) !important;
}
.msg-transfer-card .msg-transfer-divider {
  margin: var(--transfer-divider-margin) !important;
}

/* 转账卡片内部文字跟随气泡文字色 */
.msg-me .msg-transfer-card,
.msg-me .msg-transfer-card * {
  color: var(--bubble-me-color) !important;
}
.msg-them .msg-transfer-card,
.msg-them .msg-transfer-card * {
  color: var(--bubble-them-color) !important;
}

.bubble-me-custom.no-padding::after,
.bubble-them-custom.no-padding::after,
.msg-me:has(.no-padding) .bubble-me-custom::after,
.msg-them:has(.no-padding) .bubble-them-custom::after,
.bubble-me-custom:has(img)::after,
.bubble-them-custom:has(img)::after,
.bubble-me-custom:has([class*="sticker"])::after,
.bubble-them-custom:has([class*="sticker"])::after,
.bubble-me-custom:has([class*="emoji"])::after,
.bubble-them-custom:has([class*="emoji"])::after {
    display: none !important;
}

/* 图片/表情气泡本身透明化并去除边框和滤镜 */
.bubble-me-custom:has(img),
.bubble-them-custom:has(img),
.bubble-me-custom:has([class*="sticker"]),
.bubble-them-custom:has([class*="sticker"]),
.bubble-me-custom:has([class*="emoji"]),
.bubble-them-custom:has([class*="emoji"]) {
  border: none !important;
  box-shadow: none !important;
  background: transparent !important;
  filter: none !important;
  border-radius: 0 !important;
}

.bubble-me-custom img,
.bubble-them-custom img,
.bubble-me-custom [class*="sticker"],
.bubble-them-custom [class*="sticker"],
.bubble-me-custom [class*="emoji"],
.bubble-them-custom [class*="emoji"] {
  max-width: 95px !important;
  max-height: 95px !important;
  width: auto !important;
  height: auto !important;
}

/* ==========================================
   头像显示规则与布局
   ========================================== */

.msg-avatar-them-container,
.msg-avatar-me-container {
  display: none !important;
}

.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  display: flex !important;
  align-items: flex-start !important;
}

.msg-avatar-me-container.is-last,
.msg-avatar-me-container.is-single {
  display: flex !important;
  align-items: flex-end !important;
}

.msg-them.msg-bubble-wrapper {
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
}
.msg-them .msg-avatar-them-container {
  order: -1 !important;
  margin-bottom: 7px !important;
}

.msg-me.msg-bubble-wrapper {
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-end !important;
}
.msg-me .msg-avatar-me-container {
  order: 999 !important;
  margin-top: 7px !important;
}

/* ==========================================
   🎯 连续气泡间距缩小 (只挤压气泡，不碰头像)
   ========================================== */

/* 第一条：减小它底部的间距，让它贴近下一条 */
.msg-me.is-first, .msg-them.is-first,
.msg-me:has(.is-first), .msg-them:has(.is-first) {
  margin-bottom: 2.2px !important;
}

/* 中间条：减小它上下两端的间距，让它紧贴上下气泡 */
.msg-me.is-mid, .msg-them.is-mid,
.msg-me:has(.is-mid), .msg-them:has(.is-mid) {
  margin-top: 2.2px !important;
  margin-bottom: 2.2px !important;
}

/* 最后一条：减小它顶部的间距，让它贴近上一条 */
.msg-me.is-last, .msg-them.is-last,
.msg-me:has(.is-last), .msg-them:has(.is-last) {
  margin-top: 2.2px !important;
}

/* ==========================================
   🌐 翻译独立气泡（文字中心压气泡下边框 + 适度黑描边）
   ========================================== */

/* 1. 隐藏气泡内部的翻译 */
.msg-translation-wrapper {
  display: none !important;
}

/* 2. 启用独立翻译气泡；负 margin 让文字整体上提 */
.msg-translation-detached {
  display: block !important;
  margin-top: -6px !important;
  max-width: 100% !important;
  width: fit-content !important;
  box-sizing: border-box !important;
  position: relative !important;
  z-index: 3 !important;
}

/* 3. 翻译内容：白字 + 适度黑描边 */
.msg-translation-detached-content {
  background: transparent !important;
  padding: 0 !important;
  font-size: 12.5px !important;       /* 13px → 12.5px，缩小 0.5px */
  line-height: 1.2 !important;
  word-break: break-word !important;
  box-sizing: border-box !important;
  font-style: normal !important;
  font-weight: 700 !important;
  letter-spacing: 0.3px !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  border: none !important;

  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  -webkit-text-stroke: 0.9px #000000 !important;
  paint-order: stroke fill !important;
  text-shadow:
    -1px -1px 0 #000,
     0   -1px 0 #000,
     1px -1px 0 #000,
    -1px  0    0 #000,
     1px  0    0 #000,
    -1px  1px 0 #000,
     0    1px 0 #000,
     1px  1px 0 #000 !important;
}

/* 4. 对方翻译：靠左 */
.msg-translation-detached-them {
  align-self: flex-start !important;
  padding-left: 8px !important;
}

/* 5. 我方翻译：靠右 */
.msg-translation-detached-me {
  align-self: flex-end !important;
  padding-right: 8px !important;
}

/* ==========================================
   📎 独立引用条（双方镜像对称：图标外侧 + Quote + 淡灰荧光条）
   ========================================== */

/* 1. 隐藏气泡内部的引用块 */
.msg-reply-block {
  display: none !important;
}

/* 2. 启用独立引用条 - 无背景 */
.msg-reply-block-detached {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  margin-top: 4px !important;
  max-width: 100% !important;
