   ========================================== */

.msg-reply-detached-them {
  position: relative !important;
  padding-right: 22px !important;
}

.msg-reply-detached-them::after {
  content: "" !important;
  position: absolute !important;
  right: 0 !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  width: 16px !important;
  height: 16px !important;
  background: url("https://imgbed.heliar.top/i/ha6eURb9yhtebNV__retouch_2026102109521268_edit_576587445618536.png") no-repeat center / contain !important;
