  /* 🐕 */ --pay-head-h: 120px;         /* 头部高度 */
  /* 🐕 */ --pay-bear: url("https://i.postimg.cc/3R6Csy3f/quality-restoration-20261019162735736.png");
  /* 🐕 */ --pay-logo: url("https://i.postimg.cc/nrDYpHzv/quality-restoration-20261019162914874.png");
  /* 🐕 */ --pay-bear-h: 110px;         /* 小熊高度 */
  /* 🐕 */ --pay-bear-drop: 19px;       /* 小熊伸进白色区域的深度 */
  /* 🐕 */ --pay-bear-right: 8px;       /* 小熊离右边的距离 */
  /* 🐕 */ --pay-shift-them: -4px;      /* AI 卡片：正数往右，负数往左 */
  /* 🐕 */ --pay-shift-me: -8px;        /* 我方卡片：负数往左，正数往右 */
  /* 🐕 */ --pay-logo-size: 24px;       /* 底栏小图大小 */
  /* 🐕 */ --pay-logo-left: 12px;       /* 小图离卡片左边 */
  /* 🐕 */ --pay-logo-gap: 2px;         /* 小图和文字之间 */
  /* 🐕 */ --pay-anim-dur: 0.6s;        /* 收款动画时长 */
}

/* --- 0. 红包自带的红色 / 金色变量改成白底黑字 --- */
