/* 7. 按钮：默认 / 已领取 / 已退回 */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .msg-redpacket-card.msg-redpacket-card .msg-transfer-status-text::after {
