div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .msg-redpacket-card.msg-redpacket-card:is(.msg-transfer-success, .is-opened) .msg-transfer-status-text::after {
