  color: #FFFFFF !important;
  font-size: 11px !important;
  background: transparent !important;
  margin: 0 !important;
  padding: 0 !important;
  text-shadow: none !important;
}
div.chat-detail-screen:not(#_k) .msg-translation-detached-content::before,
div.chat-detail-screen:not(#_k) .msg-translation-detached-content::after,
div.chat-detail-screen:not(#_k) .msg-translation-detached :is(svg, img) {
  content: none !important;
  display: none !important;
}

/* 5. 带翻译的这条和下一条不额外留距离 */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper:has(.msg-translation-detached):not(.is-last):not(.is-single) {
