  margin-top: 0 !important;
}
:has(.msg-bubble-wrapper.msg-them.is-single) + * .msg-bubble-wrapper.msg-me:is(.is-first, .is-single):has(.msg-reply-block-detached)::after {
  content: "";
  position: absolute;
  left: var(--q-arc-edge);
  top: var(--q-arc-y);
  width: 36px;
  height: 28px;
  pointer-events: none;
