/* ==  亮色背景覆盖层（删掉这一段即恢复暗色）== */
:root {
  /* 对方：亮色毛玻璃（纯白壁纸看不清气泡的话，换成 rgba(120,120,128,0.16) 的灰调） */
  --bubble-them-bg: rgba(255, 255, 255, 0.62);
  --bubble-them-color: #111;
  /* 对方液态描边：左上白高光，右下淡灰收边 */
  --them-rim: linear-gradient(135deg,
    rgba(255, 255, 255, 0.95) 0%,
    rgba(0, 0, 0, 0.07) 35%,
    rgba(0, 0, 0, 0.06) 65%,
    rgba(0, 0, 0, 0.20) 100%);
  /* 按钮/胶囊的锥形描边：顶部白高光，底部淡灰 */
  --rim-conic: conic-gradient(from 0deg,
    rgba(255, 255, 255, 0.95) 0deg, rgba(255, 255, 255, 0.60) 40deg,
    rgba(0, 0, 0, 0.08) 90deg, rgba(0, 0, 0, 0.14) 140deg,
    rgba(0, 0, 0, 0.22) 180deg, rgba(0, 0, 0, 0.14) 220deg,
    rgba(0, 0, 0, 0.08) 270deg, rgba(255, 255, 255, 0.60) 320deg,
    rgba(255, 255, 255, 0.95) 360deg);
  --r-them-bg: #e5e5ea;                         /* 对方贴的表情徽章：浅灰 */
  --image-msg-shadow: 0 4px 14px rgba(0, 0, 0, 0.12);
  --light-ink: #1c1c1e;                         /* 图标和文字的深色 */
  --light-ink-soft: rgba(60, 60, 67, 0.60);
}

