  inset: 0 !important;
  border-radius: inherit !important;
  padding: 0.8px !important;
  pointer-events: none !important;
  display: block !important;
  z-index: 0 !important;

  background: conic-gradient(
    from 0deg,
    rgba(255, 255, 255, 0.70) 0deg,
    rgba(255, 255, 255, 0.45) 40deg,
    rgba(255, 255, 255, 0.20) 75deg,
    rgba(255, 255, 255, 0.18) 90deg,
    rgba(255, 255, 255, 0.20) 105deg,
    rgba(255, 255, 255, 0.40) 140deg,
    rgba(255, 255, 255, 0.60) 180deg,
    rgba(255, 255, 255, 0.40) 220deg,
    rgba(255, 255, 255, 0.20) 255deg,
    rgba(255, 255, 255, 0.18) 270deg,
    rgba(255, 255, 255, 0.20) 285deg,
    rgba(255, 255, 255, 0.45) 320deg,
    rgba(255, 255, 255, 0.70) 360deg
