.msg-reply-detached-name { filter: invert(1); opacity: 0.55; }    /* 弧线：白色反成深色 */
.msg-bubble-wrapper:has(.msg-reply-block-detached)::after { filter: invert(1); opacity: 0.55; }

/* ---------- 图片 ---------- */
.chat-detail-screen .msg-bubble-wrapper .msg-image-wrapper {
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.10) !important;
}

/* ---------- 打字气泡 ---------- */
.nuo-typing-indicator { --typing-dot-color: rgba(60, 60, 67, 0.55); }
.nuo-typing-bubble::after { filter: invert(1); opacity: 0.45; }

/* ---------- 转账卡片：对方那张改成偏深的灰，保证白字看得清 ---------- */
.msg-them .msg-transfer-card {
  background: linear-gradient(180deg,
    rgba(110, 110, 118, 0.62) 0%, rgba(90, 90, 98, 0.52) 50%, rgba(70, 70, 78, 0.46) 100%) !important;
}

/* ---------- 长按菜单 ---------- */
.chat-detail-screen .ig-context-menu,
