/* 🔙 返回键 */
.chat-header-custom:has(.header-profile-section) .header-btn-back {
  background-image: url('https://i.imgant.com/v2/dQsgUPU.png') !important;
  width: 40px !important; height: 40px !important;          
  background-size: 35px 40px !important;         /* 👇 这里改返回键图标的大小 */
  background-position: center left !important; 
