/* ===================================================
   QQ 主题定制 - 聊天区域终极整合版
   目录：
   1️⃣ 全局气泡颜色与基础设置
   2️⃣ 胶囊气泡与三角小尾巴
   3️⃣ 智能去气泡 (隐藏图片/语音/盲盒的尾巴)
   4️⃣ 独立语音条定制 (白卡+短波形)
   5️⃣ 盲盒长图定制 (点击揭晓)
   6️⃣ 引用消息定制 (自带时间和贴纸)
   7️⃣ 电影字幕级翻译
   8️⃣ 思维链定制 (诗意文案)
   9️⃣ 转账卡片
   =================================================== */

/* =======================================
   1️⃣ 全局气泡颜色与基础设置
   ======================================= */
.chat-detail-screen {
  /* 我方气泡：极浅冰雪蓝 + 黑字 */
  --bubble-me-bg: #F5FAFF !important;      
  --bubble-me-color: #000000 !important;   

  /* 对方气泡：极浅灰白 + 黑字 */
  --bubble-them-bg: #F9F9F9 !important;    
  --bubble-them-color: #000000 !important; 

  /* 气泡内间距，紧凑排版 */
  --bubble-me-padding: 7px 12px !important;
  --bubble-them-padding: 7px 12px !important;

  /* 移除自带边框 */
  --bubble-me-border: none !important;
  --bubble-them-border: none !important;
  /* 🌟 因为气泡变白了，这里加上一层极弱的阴影，让它从背景里浮出来 */
  --bubble-me-shadow: 0 2px 8px rgba(0,0,0,0.04) !important;
  --bubble-them-shadow: 0 2px 8px rgba(0,0,0,0.04) !important;

  /* 全圆角：完美的圆润小胶囊 */
  --bubble-me-radius: 18px !important;
  --bubble-me-radius-first: 18px !important;
  --bubble-me-radius-mid: 18px !important;
  --bubble-me-radius-last: 18px !important;

  --bubble-them-radius: 18px !important;
  --bubble-them-radius-first: 18px !important;
  --bubble-them-radius-mid: 18px !important;
  --bubble-them-radius-last: 18px !important;
}

/* =======================================
   2️⃣ 胶囊气泡与三角小尾巴
   ======================================= */
/* 解除边界裁切 */
.chat-detail-screen .bubble-me-custom,
.chat-detail-screen .bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
}

/* 我方小尾巴 (右下角) */
.chat-detail-screen .bubble-me-custom::before {
  content: "" !important;
  position: absolute !important;
  width: 16px !important;    
  height: 6px !important;    
  bottom: 4px !important;
  right: -5px !important;    
  background: var(--bubble-me-bg) !important;
  clip-path: polygon(50% 0, 0 100%, 100% 100%) !important; 
}

/* 对方小尾巴 (左下角) */
.chat-detail-screen .bubble-them-custom::before {
  content: "" !important;
  position: absolute !important;
  width: 16px !important;
  height: 6px !important;
  bottom: 4px !important;
  left: -5px !important;     
  background: var(--bubble-them-bg) !important;
  clip-path: polygon(50% 0, 0 100%, 100% 100%) !important; 
}

/* =======================================
   3️⃣ 智能去气泡 (精准猎杀单独表情包，绝对防误伤引用)
   ======================================= */

/* 
   核心逻辑：
   1. 侦测常规卡片：语音、盲盒长图、转账、通话
   2. 侦测表情包/图片：只要气泡里包含 img 标签，就判定为表情包
   3. 🌟 绝对防误伤：使用 :not(:has(.msg-reply-block-name))，只要气泡里带有“引用”，就立刻停止透明化，完美保留气泡底色和尾巴！
*/
.chat-detail-screen .bubble-me-custom:has(.voice-msg, .msg-sim-card, .msg-transfer-card, [class*="call" i]),
.chat-detail-screen .bubble-them-custom:has(.voice-msg, .msg-sim-card, .msg-transfer-card, [class*="call" i]),
.chat-detail-screen .bubble-me-custom:has(img):not(:has(.msg-reply-block-name)),
.chat-detail-screen .bubble-them-custom:has(img):not(:has(.msg-reply-block-name)) {
  background: transparent !important;
  padding: 0 !important;
  box-shadow: none !important;
}

/* 强行抹除它们的小尾巴 */
.chat-detail-screen .bubble-me-custom:has(.voice-msg, .msg-sim-card, .msg-transfer-card, [class*="call" i])::before,
.chat-detail-screen .bubble-them-custom:has(.voice-msg, .msg-sim-card, .msg-transfer-card, [class*="call" i])::before,
.chat-detail-screen .bubble-me-custom:has(img):not(:has(.msg-reply-block-name))::before,
.chat-detail-screen .bubble-them-custom:has(img):not(:has(.msg-reply-block-name))::before {
  display: none !important;
}

/* 抵消图片/表情包自带的多余边距，让它对齐得更完美 */
.chat-detail-screen .msg-image-wrapper,
.chat-detail-screen .msg-bubble-container > img {
  margin: 0 !important; 
}

/* =======================================
   4️⃣ 独立语音条定制 (白卡 + 短波形)
   ======================================= */
.chat-detail-screen {
  --voice-toggle-display: flex !important;

  /* 独立的白色转写气泡 */
  --voice-transcription-bg: #FFFFFF !important;       
  --voice-transcription-color: #000000 !important;    
  --voice-transcription-radius: 12px !important;      
  --voice-transcription-padding: 8px 12px !important;
  --voice-transcription-margin-top: 6px !important;  

  /* 缩小播放键和波形高度 */
  --voice-play-btn-size: 26px !important;
  --voice-waveform-height: 18px !important;
}

/* 重新在语音条上绘制气泡底色和小尾巴 */
.chat-detail-screen .voice-msg,
.chat-detail-screen .voice-controls-row {
  padding: 5px 10px !important;
  border-radius: 16px !important;
  position: relative !important;
  overflow: visible !important; 
}
.chat-detail-screen .voice-msg-me .voice-controls-row {
  background: var(--bubble-me-bg) !important;
  color: var(--bubble-me-color) !important;
}
.chat-detail-screen .voice-msg-me .voice-controls-row::before {
  content: "" !important; position: absolute !important;
  width: 16px !important; height: 6px !important;    
  bottom: 4px !important; right: -5px !important;    
  background: var(--bubble-me-bg) !important;
  clip-path: polygon(50% 0, 0 100%, 100% 100%) !important; 
}
.chat-detail-screen .voice-msg-them .voice-controls-row {
  background: var(--bubble-them-bg) !important;
  color: var(--bubble-them-color) !important;
}
.chat-detail-screen .voice-msg-them .voice-controls-row::before {
  content: "" !important; position: absolute !important;
  width: 16px !important; height: 6px !important;
  bottom: 4px !important; left: -5px !important;     
  background: var(--bubble-them-bg) !important;
  clip-path: polygon(50% 0, 0 100%, 100% 100%) !important; 
}

/* 极简短波形裁切 */
.chat-detail-screen .voice-waveform {
  width: 45px !important;    
  min-width: 45px !important;
  overflow: hidden !important; 
  display: flex !important;
  justify-content: flex-start !important;
  margin: 0 8px !important;       
}
.chat-detail-screen .voice-waveform-bar {
  width: 3px !important;
  min-width: 3px !important;
  margin-right: 3px !important;
  border-radius: 2px !important;
}
/* 🌟 波形颜色全黑，搭配浅色气泡 */
.chat-detail-screen .voice-msg-me .voice-waveform-bar { background: #000000 !important; }
.chat-detail-screen .voice-msg-them .voice-waveform-bar { background: #000000 !important; }

/* 播放键定制：毛玻璃底 + 实心图标 */
.chat-detail-screen .voice-play-btn {
  background: rgba(0, 0, 0, 0.05) !important; 
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  border-radius: 50% !important;
  z-index: 2 !important;
}
.chat-detail-screen .voice-msg-me .voice-play-btn svg { fill: #000000 !important; stroke: #000000 !important; }
.chat-detail-screen .voice-msg-them .voice-play-btn svg { fill: #000000 !important; stroke: #000000 !important; }

/* 点击秒数展开文字 (隐形开关) */
.chat-detail-screen .voice-transcription-toggle {
  position: absolute !important;
  top: 0 !important; right: 0 !important;         
  width: 45px !important; height: 100% !important;     
  opacity: 0 !important; z-index: 10 !important;      
}

/* 独立的白底转写气泡排版 */
.chat-detail-screen .voice-transcription {
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1) !important;
  align-self: flex-end !important;
  width: max-content !important;
  max-width: 100% !important;
}
.chat-detail-screen .voice-msg-them .voice-transcription {
  align-self: flex-start !important;
}

/* =======================================
   5️⃣ 盲盒长图 (.msg-sim-card) 正方形美化
   ======================================= */
.chat-detail-screen .msg-sim-card {
  width: 150px !important;
  height: 150px !important;
  position: relative !important;
  overflow: hidden !important;
  border-radius: 8px !important;
  cursor: pointer !important;
  background-color: #ffffff !important; 
}

/* 封面贴图，盖在最上面 */
.chat-detail-screen .msg-sim-card::after {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background-image: url('https://i.imgant.com/v2/1Svz68X.jpeg');
  background-size: cover;
  background-position: center;
  z-index: 10;
  transition: opacity 0.2s ease-in-out;
}

/* 点击长按时，隐藏封面露出里面的文字 */
.chat-detail-screen .msg-sim-card:active::after {
  opacity: 0 !important;
  pointer-events: none !important;
}

/* =======================================
   6️⃣ 引用消息定制 (自带时间和贴纸)
   ======================================= */
.chat-detail-screen {
  --reply-block-radius: 12px !important;
  --reply-block-padding: 8px 10px !important;

  --reply-me-bg: rgba(0, 0, 0, 0.04) !important;
  --reply-me-name-color: #000000 !important;
  --reply-me-text-color: rgba(0, 0, 0, 0.6) !important;
  --reply-me-border-left: 3px solid #B0D4FF !important; /* 配合我方气泡蓝色的边线 */

  --reply-them-bg: rgba(0, 0, 0, 0.04) !important;
  --reply-them-name-color: #000000 !important;
  --reply-them-text-color: rgba(0, 0, 0, 0.6) !important;
  --reply-them-border-left: 3px solid #D0D0D0 !important; /* 配合对方白色的边线 */
}

/* 名字容器排版 */
.chat-detail-screen .msg-reply-block-name {
  display: inline-flex !important;
  align-items: center !important;
  max-width: 100% !important; 
}

/* 伪造的时间文字 */
.chat-detail-screen .msg-reply-block-name::before {
  content: "刚刚" !important;    
  order: 2 !important;           
  display: inline-block !important;
  font-size: 11px !important;
  font-weight: normal !important;
  opacity: 0.6 !important;
  white-space: nowrap !important;
  pointer-events: none !important;
  margin-left: 6px !important;                   
  transform: translateY(0px) !important;         
}

/* 右侧跟随的贴纸 */
.chat-detail-screen .msg-reply-block-name::after {
  content: "" !important;
  order: 3 !important;           
  display: inline-block !important;
  flex-shrink: 0 !important;     
  width: 35px !important;        
  height: 25px !important;       
  background-image: url('https://i.imgant.com/v2/dpZ6LJe.png') !important;
  background-size: contain !important; 
  background-position: center !important;
  background-repeat: no-repeat !important;
  opacity: 0.8 !important;       
  pointer-events: none !important;
  margin-left: 100px !important;                   
  transform: translateY(-1px) !important;         
}

/* =======================================
   7️⃣ 电影字幕级翻译
   ======================================= */
.chat-detail-screen .msg-translation-wrapper {
  display: none !important;
}

.chat-detail-screen .msg-translation-detached {
  display: flex !important;
  width: fit-content !important;
  max-width: 95% !important;   
  margin-top: -4px !important; 
  z-index: 1 !important; 
}

.chat-detail-screen .msg-bubble-wrapper {
  z-index: 2 !important; 
  position: relative !important;
}

.chat-detail-screen .msg-translation-detached-content {
  background: transparent !important;   
  color: #333333 !important; /* 翻译文字改为深色 */           
  border: none !important;              
  padding: 0 4px !important;            
  font-size: 13px !important;           
  line-height: 1.4 !important;
  opacity: 0.9 !important;             
  text-shadow: none !important; /* 去掉翻译阴影 */
