}

.chat-detail-screen .msg-translation-detached-them {
  align-self: flex-start !important;
  margin-left: 20px !important; 
}
.chat-detail-screen .msg-translation-detached-me {
  align-self: flex-end !important;
  margin-right: 20px !important;
} 

/* =======================================
   8️⃣ 思维链定制 (诗意文案)
   ======================================= */
.chat-detail-screen {
  /* 按钮文字、箭头、展开后的正文，全都变成静谧灰蓝 */
  --thinking-btn-color: #7AA2D9 !important;
  --thinking-arrow-color: #7AA2D9 !important;
  --thinking-text-color: #7AA2D9 !important;

  /* 🌟 使用我方气泡纯色蓝，不带透明度，并且按钮和面板统一底色 */
  --thinking-btn-bg: #F5FAFF !important; 
  --thinking-panel-bg: #F5FAFF !important; 

  /* 🌟 强制关闭毛玻璃效果 */
  --thinking-panel-backdrop: none !important; 

  --thinking-panel-border-left: 2px solid #B0D4FF !important; 
  --thinking-panel-radius: 12px !important;
}

.chat-detail-screen .nuo-thinking-label { font-size: 0 !important; }
.chat-detail-screen .nuo-thinking-icon { display: none !important; }

/* 你的专属文案 */
.chat-detail-screen .nuo-thinking-label::after {
  content: "對於你而言  我衹是一顆星嗎？" !important;
  color: #7AA2D9 !important; /* 🌟 强制这句话变成蓝色 */
  font-size: 12px !important;
  letter-spacing: 0.5px !important; 
}

/* =======================================
   💸 9️⃣ QQ 写实版转账卡片 (采纳你的完美架构版)
   ======================================= */

:root {
  /* 🔪 彻底抽空原生黑点底座、各种状态的警示灯和边框 */
  --transfer-icon-bg: transparent !important;
  --transfer-me-icon-bg: transparent !important;
  --transfer-them-icon-bg: transparent !important;
  --transfer-success-icon-bg: transparent !important;
  --transfer-rejected-icon-bg: transparent !important;
  --transfer-expired-icon-bg: transparent !important;
  --transfer-card-border: none !important;
  --transfer-me-card-border: none !important;
  --transfer-them-card-border: none !important;
}

/* === 1. 卡片状态变色 === */
/* 默认状态：QQ 亮蓝 */
.chat-detail-screen .msg-transfer-card {
  width: 220px !important;
  height: 85px !important;
  background-color: #1BA3FF !important; 
  border-radius: 12px !important;        
  position: relative !important;
  padding: 0 !important; 
  overflow: hidden !important; 
  display: block !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}
/* 已收款状态：浅蓝色 */
.chat-detail-screen .msg-transfer-card.msg-transfer-success {
  background-color: #7BBEFF !important; 
}
/* 拒收 / 过期状态：浅灰色 */
.chat-detail-screen .msg-transfer-card.msg-transfer-rejected,
.chat-detail-screen .msg-transfer-card.msg-transfer-expired-card {
  background-color: #D4D4D4 !important; 
}

/* === 2. 画出底部的极细白线 === */
.chat-detail-screen .msg-transfer-card::before {
  content: "";
  position: absolute;
  bottom: 24px; left: 12px; right: 12px; height: 1px;
  background-color: rgba(255, 255, 255, 0.25) !important;
  transform: scaleY(0.5); /* 压成 0.5px 的极细线 */
  z-index: 1;
}

/* === 3. 隐藏系统默认图标和原生分割线 === */
.chat-detail-screen .msg-transfer-card svg,
.chat-detail-screen .msg-transfer-divider {
  display: none !important;
}

/* === 4. 左侧贴上 QQ 转账贴图 === */
.chat-detail-screen .msg-transfer-card::after {
  content: "";
  position: absolute;
  top: 12px; left: 12px; width: 38px; height: 38px;
  background-image: url('https://i.imgant.com/v2/r7FlGkx.png');
  background-size: 100% 100%; background-repeat: no-repeat; z-index: 2;
}

/* === 5. 调整金额文字 (强制染白，破除系统变黑诅咒) === */
.chat-detail-screen .msg-transfer-amount {
  position: absolute !important;
  top: 14px !important;
  left: 60px !important;      
  z-index: 2 !important;
  display: flex !important;           
  flex-direction: row !important;
  align-items: baseline !important;   
  white-space: nowrap !important;     
}
.chat-detail-screen .msg-transfer-amount,
.chat-detail-screen .msg-transfer-amount * {
  color: #ffffff !important;  
  -webkit-text-fill-color: #ffffff !important; /* 🌟 强制填充色，绝对白！ */
  font-size: 16px !important;
  font-weight: bold !important;
  line-height: 1 !important;
  background: transparent !important; 
}

/* === 6. 自定义备注文字：眼泪好烫... === */
.chat-detail-screen .msg-transfer-label {
  position: absolute !important; 
  top: 36px !important;            
  left: 60px !important;
  z-index: 2 !important; 
  font-size: 0 !important; /* 🌟 隐藏系统原生文本 */
}
.chat-detail-screen .msg-transfer-label::after {
  content: "眼泪好烫 爱也是这个温度吗" !important;
  color: rgba(255, 255, 255, 0.8) !important; 
  -webkit-text-fill-color: rgba(255, 255, 255, 0.8) !important; 
  font-size: 12px !important; 
}

/* === 7. 底部写上“转账”二字 === */
.chat-detail-screen .msg-transfer-status-text {
  position: absolute !important; bottom: 5px !important; left: 14px !important; font-size: 0 !important; z-index: 2 !important; margin: 0 !important; padding: 0 !important; background: transparent !important;
}
.chat-detail-screen .msg-transfer-status-text::after {
  content: "转账" !important; font-size: 11px !important; color: #ffffff !important; -webkit-text-fill-color: #ffffff !important; 
}

/* === 8. 终极物理清理机：彻底隐藏多余系统垃圾 === */

/* 1. 扩大暗杀名单：把倒计时可能用到的 class 全部抹除 */
.chat-detail-screen .msg-transfer-subtitle,
.chat-detail-screen .msg-transfer-card [class*="expire" i],
.chat-detail-screen .msg-transfer-card [class*="time" i],
.chat-detail-screen .msg-transfer-card [class*="count" i], /* 狙击 countdown */
.chat-detail-screen .msg-transfer-card [class*="timer" i], /* 狙击 timer */
.chat-detail-screen .msg-transfer-card [class*="note" i],  /* 狙击 note */
.chat-detail-screen .msg-transfer-card [class*="dot" i],
.chat-detail-screen .msg-transfer-card [class*="unread" i],
.chat-detail-screen .msg-transfer-status-text *,
.chat-detail-screen .msg-transfer-label * {
  display: none !important; 
}

/* 2. 核弹级兜底：把卡片里所有未知的文字强制变透明（排除你保留的核心元素） */
.chat-detail-screen .msg-transfer-card *:not(.msg-transfer-amount):not(.msg-transfer-amount *):not(.msg-transfer-label):not(.msg-transfer-status-text) {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  font-size: 0 !important;
  letter-spacing: -999px !important;
}

/* 为了防止原生卡片自动拉长导致底部露馅，死死锁住高度和溢出 */
.chat-detail-screen .msg-transfer-card {
  max-height: 85px !important;
  min-height: 85px !important;
}

/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ ===================================================
   QQ 主题定制 - 顶栏终极版 (带详细修改说明注释)
   =================================================== */

/* === 1. 顶栏整体控制 (底色、毛玻璃、高度) === */
.chat-header-custom:has(.header-profile-section) {
  /* 基础变量锁定（字体颜色、头像变圆等） */
  --chat-header-title-color: #C89546 !important;     
  --chat-header-title-size: 16px !important;         
  --chat-header-title-weight: 600 !important;        
  --chat-header-avatar-size: 34px !important;        /* 头像的大小 */
  --chat-header-avatar-radius: 50% !important;       /* 头像圆角：50%就是正圆形 */
  --chat-header-avatar-border: none !important;

  /* 👇 顶栏的高度，想改顶栏整体有多高，改这里（两处都要一样） 👇 */
  height: 95px !important;
  min-height: 95px !important;
  align-items: center !important;

  /* 顶栏悬浮设置 (不要动这里，保证滑动能穿透) */
  position: absolute !important;
  top: 0 !important; left: 0 !important; right: 0 !important;
  z-index: 100 !important;

  /* 👇 顶栏的颜色和毛玻璃透明度 👇 */
  /* 0.9 是透明度。如果你想让背后的消息透出来更多，改成 0.7 左右 */
  background: rgba(17, 17, 17, 0.9) !important;
  backdrop-filter: blur(25px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(25px) saturate(180%) !important;

  /* 顶栏最下方的一根极细高光分隔线 */
  border-bottom: 1px solid rgba(255, 255, 255, 0.05) !important;
}

/* === 2. 消息列表排版 (防止第一条消息被顶栏挡住) === */
.chat-messages-area {
  height: 100% !important;
}
.chat-message-list-custom {
  /* 如果你把顶栏调高了，这里的 55px 也要跟着调大，不然消息会被压住 */
  padding-top: calc(env(safe-area-inset-top, 0px) + 95px) !important;
}

/* === 3. 🌟头像和名字的整体位置 (包含底下的状态也会跟着走) === */
.header-profile-section {
  position: relative !important;

  /* 👇 想改头像和名字的整体位置，就在这里改！ 👇 */
  /* translate(左右像素, 上下像素)。负数代表向左/向上，正数代表向右/向下 */
  /* 比如：translate(-15px, 2px) 就是向左移15px，向下移2px */
  transform: translate(-15px, -5px) !important; 
}

/* === 4. 名字与右侧双贴纸 === */
.chat-header-custom:has(.header-profile-section) .chat-header-title {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  transform: translateY(-8px) !important; 
  white-space: nowrap !important; /* 强制不换行 */

  /* 🌟 给名字加上相对定位，作为贴纸的固定锚点 */
  position: relative !important; 
}

/* 彻底悬浮的右侧贴纸画板 */
.chat-header-custom:has(.header-profile-section) .chat-header-title::after {
  content: "" !important;

  /* 🌟 核心魔法：改成绝对定位，让它彻底脱离排版，不占一丝空间！ */
  position: absolute !important;
  left: 100% !important;          /* 紧紧贴在名字的最右侧 */
  top: 50% !important;            /* 配合向上的Y轴位移，实现垂直居中 */
  transform: translateY(-50%) !important;

  pointer-events: none !important; /* 🌟 防止贴纸挡住底下的按钮点击 */

  /* 画板大小还是 200px，但因为飘起来了，再也不会挤走设置键 */
  margin-left: -15px !important;       
  width: 200px !important;            
  height: 40px !important;           

  /* 贴纸图片和位置 (完全保留你原本调好的参数) */
  background-image: 
    url('https://i.imgant.com/v2/hdAgDDw.png'),  
    url('https://i.imgant.com/v2/V3SwePF.png') !important; 
  background-repeat: no-repeat, no-repeat !important;
  background-size: 63px 23px, 80px 35px !important;  
  background-position: 18px 9px, 80px -1px !important;  
}

/* === 5. 在线状态 & 绿色呼吸灯 === */
/* 隐藏旧状态 */
.chat-header-custom:has(.header-profile-section) .chat-header-subtitle { 
  display: none !important; 
}

/* 强制注入文字：iPhone 17 Pro Max 在线 */
.header-profile-section::after {
  content: "iPhone 17 Pro Max在线" !important;
  position: absolute !important;

  /* 👇 想改“在线文字”的位置，改这里 👇 */
  bottom: -2px !important;          /* 上下位置：负数越大越靠下 */
  left: 56px !important;            /* 左右位置：数值越大越靠右 */

  font-size: 11px !important;       /* 文字大小 */
  color: #ffffff !important;        /* 文字颜色 */
  white-space: nowrap !important;
  pointer-events: none !important;
}

/* 强制注入绿色呼吸灯小圆点 */
.header-profile-section::before {
  content: "" !important;
  position: absolute !important;

  /* 👇 想改“绿点”的位置，改这里 👇 */
  bottom: 2px !important;          /* 上下位置 */
  left: 42px !important;            /* 左右位置，需要和上面的文字配合对齐 */

  width: 6px !important;            /* 绿点宽度 */
  height: 6px !important;           /* 绿点高度 */
  border-radius: 50% !important;
  background-color: #10B981 !important; /* 绿点颜色 */
  box-shadow: 0 0 6px rgba(16, 185, 129, 0.6) !important;
  animation: qq-online-pulse 2s infinite ease-in-out !important; 
  pointer-events: none !important;
}

@keyframes qq-online-pulse {
  0% { opacity: 0.5; transform: scale(0.9); box-shadow: 0 0 2px rgba(16, 185, 129, 0.4); }
  50% { opacity: 1; transform: scale(1.1); box-shadow: 0 0 8px rgba(16, 185, 129, 0.9); }
  100% { opacity: 0.5; transform: scale(0.9); box-shadow: 0 0 2px rgba(16, 185, 129, 0.4); }
}

/* === 6. 所有按键精细调节 === */
/* 隐藏默认 SVG 图标 */
.chat-header-custom:has(.header-profile-section) .header-btn-back svg,
.chat-header-custom:has(.header-profile-section) .header-btn-phone svg,
