/* ===================================================
   QQ 主题定制 - 第二部分：底栏输入区 (扁平化无阴影版)
   =================================================== */

.chat-detail-screen {
  /* 输入框颜色更浅：0.45，更晶莹剔透 */
  --input-box-bg: rgba(60, 60, 60, 0.4) !important; 
  --input-box-color: #ffffff !important;
  --input-box-radius: 8px !important;
  --input-box-border: none !important;  

  --input-box-placeholder: transparent !important;

