  --input-area-blur: 25px !important;                  
  --input-area-border-top: none !important; 
}

/* === 底栏整体高度调节 === */
.chat-detail-screen .input-area-custom {
  position: absolute !important;
  bottom: 0 !important; left: 0 !important; right: 0 !important;
  z-index: 100 !important;

  padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 25px) !important;
