} 

/* =======================================
   8️⃣ 思维链定制 (诗意文案)
   ======================================= */
.chat-detail-screen {
  --thinking-btn-color: #FEB4CD !important;
  --thinking-arrow-color: #FEB4CD !important;
  --thinking-text-color: #FEB4CD !important;
