    --msg-sim-shadow: 0 0 3px rgba(0, 0, 0, 0.03), 
inset 0px 0px 1px 1px rgba(255,255,255,0.07);
    --msg-sim-img1: url("https://backup.fukit.cn/autoupload/f/LrDDsXb9MBHmvh5yejuFgyfNcKcqEnRmcljopnyJoMs/20260702/Gf7p/1320X1313/IMG_8830.jpeg");
    --msg-sim-img2: url("https://backup.fukit.cn/autoupload/f/LrDDsXb9MBHmvh5yejuFgyfNcKcqEnRmcljopnyJoMs/20260703/OLJT/1320X1284/IMG_8859.jpeg");
    --msg-sim-img3: url("https://backup.fukit.cn/autoupload/f/LrDDsXb9MBHmvh5yejuFgyfNcKcqEnRmcljopnyJoMs/20260702/E0Rc/1320X1313/IMG_8822.jpeg");
}
/* 文字图 */
.msg-sim-card * {
    display: none !important;
}
.msg-sim-card {
    position: relative !important;
    overflow: visible !important;
    width: 160px !important;
    height: 210px !important;background-origin: border-box !important;
    background-clip: border-box !important;
    background-image: var(--msg-sim-img1) !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    border-radius: 10px !important;
    border: var(--msg-sim-border) !important;
    box-shadow: var(--msg-sim-shadow) !important;
    margin-right: 26px !important;
}
.msg-sim-card::before {
    background-image: var(--msg-sim-img2) !important;
    transform: translateX(20px) rotate(2.5deg) scale(0.9) !important;
    z-index: -1 !important;
}
.msg-sim-card::after {
    background-image: var(--msg-sim-img3) !important;
    transform: translateX(37px) rotate(4.5deg) scale(0.8) !important;
    z-index: -2 !important;
}
.msg-sim-card::before,
.msg-sim-card::after {
    content: "" !important;
    position: absolute !important;
    inset: -0.5px  !important;
    width: 100% !important;
    height: 100% !important;
    border-radius: 10px !important;
    border: var(--msg-sim-border) !important;
    box-shadow: var(--msg-sim-shadow) !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    background-color: transparent !important;
    pointer-events: none !important;
}

