   ======================================================== */
/* 1. 废除系统排版，赋予它们独立的点击面积和最高层级 */
.chat-detail-screen .header-btn-video,
.chat-detail-screen .header-btn-phone {
  opacity: 0 !important; 
  pointer-events: auto !important; 
  position: absolute !important; /* 👈 强制绝对定位，彻底脱离系统束缚 */
  width: 44px !important;        /* 👈 保证有足够的点击面积 */
  height: 44px !important;
  margin: 0 !important;
  padding: 0 !important;
  transform: none !important;    /* 👈 废除上次失败的平移 */
  z-index: 9999 !important;
  margin-top: var(--config-header-icon-top-right) !important;
}

/* 2. 🎥 通话记录键：死死钉在最右侧可见图标的左边 */
.chat-detail-screen .header-btn-video {
  right: 50px !important; 
}

/* 3. 📞 语音通话键：死死钉在通话记录键的更左边 */
