#chat-detail-screen .bubble-me-custom:has(.gift-ig-container),
#chat-detail-screen .bubble-them-custom:has(.msg-theater-card),
#chat-detail-screen .bubble-me-custom:has(.msg-theater-card),
#chat-detail-screen .bubble-them-custom:has(.msg-offline-invite-card),
#chat-detail-screen .bubble-me-custom:has(.msg-offline-invite-card),
#chat-detail-screen .bubble-them-custom:has(.msg-couples-invite-card),
#chat-detail-screen .bubble-me-custom:has(.msg-couples-invite-card),
#chat-detail-screen .bubble-them-custom:has(.msg-couples-response-card),
#chat-detail-screen .bubble-me-custom:has(.msg-couples-response-card),
