}

  --thinking-btn-bg:transparent;
  --thinking-btn-border:none;
  --thinking-btn-shadow:none;
  --thinking-btn-padding:0;
}

.nuo-thinking-btn{
  background:none !important;
  border:none !important;
  box-shadow:none !important;
  padding:0 !important;
}

/* 藏掉 ▶ 和 💭 */
.nuo-thinking-arrow,
.nuo-thinking-icon{
  display:none !important;
}

/* 原文字"思维链"藏掉，换成名字 */
.nuo-thinking-label{
  font-size:0 !important;
}
.nuo-thinking-label::before{
  content:var(--char-name);
  font-size:13px;
  font-weight:700;
}

