/* 右上角圆形 kakao 小徽章（用原来的图标位置来画） */
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-icon{
  position:absolute !important;
  top:-17px !important; right:-10px !important;
  width:30px !important; height:30px !important;
  margin:0 !important; padding:0 !important;
