}

/* 右侧卡通吉祥物 */
.msg-transfer-card:not(.msg-redpacket-card)::after{
  content:"" !important;
  display:block !important;
  position:absolute !important;
  top:50px !important; right:12px !important;
  width:75px !important; height:85px !important;
  background:url('https://i.postimg.cc/cJRKb2Zj/IMG-4935.png') no-repeat center bottom / contain !important;
  pointer-events:none !important;
