}

/* 不显示的东西：备注/副标题、分隔线、对勾、箭头 */
.msg-transfer-card:not(.msg-redpacket-card) :is(.msg-transfer-subtitle,.msg-transfer-divider,.msg-transfer-check,.msg-transfer-chevron){
  display:none !important;
}

/* 金额 + 원을 보냈어요 */
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount{
  position:absolute !important;
  top:calc(40% + 23px) !important; left:16px !important; right:16px !important;
  margin:0 !important; padding:0 !important;
  font-size:16px !important; font-weight:400 !important;
  line-height:1.2 !important;
  color:#1E1E1E !important;
  display:inline-block !important;
  overflow:hidden !important;
  white-space:nowrap !important;
  text-indent:var(--nj-tf-indent) !important;
  -webkit-text-stroke:0 !important;
}
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount :is(svg,img){
  display:none !important;
}
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount::after{
  content:"원을 보냈어요" !important;
  font-size:18px !important; font-weight:400 !important;
  color:#1E1E1E !important;
  margin-left:2px !important;
}

/* 状态：浅灰按钮（固定在卡片下方，离底边 48px） */
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-status-text{
  position:absolute !important;
  left:14px !important; right:14px !important; bottom:48px !important;
  height:38px !important;
  margin:0 !important; padding:0 !important;
  box-sizing:border-box !important;
  display:flex !important; align-items:center !important; justify-content:center !important;
  text-align:center !important;
  background:rgba(0,0,0,.04) !important;
  border:none !important;
  border-radius:8px !important;
  color:#1E1E1E !important;
  font-size:13.5px !important; font-weight:500 !important;
  line-height:1 !important;
}

/* 底部 카카오페이 标志 */
.msg-transfer-card:not(.msg-redpacket-card)::before{
  content:"카카오페이" !important;
  display:flex !important; align-items:center !important;
  position:absolute !important;
  bottom:10px !important; left:14px !important; right:14px !important;
