/* 大胶囊：背景 / 边框 / 阴影 / 模糊全部去掉 */
.input-action-bar-custom{
  background:none !important;
  border:none !important;
  box-shadow:none !important;
  -webkit-backdrop-filter:none !important;
          backdrop-filter:none !important;
}

:root{
  --nj-in-h:30px;        /* 输入框高度 */
  --nj-in-pad-y:9px;     /* 文字上下留白：想让文字更靠上/下就调这个 */
  --nj-r-tl:20px;        /* 左上角 */
  --nj-r-tr:20px;        /* 右上角 */
  --nj-r-br:20px;        /* 右下角 */
  --nj-r-bl:20px;        /* 左下角 */
