  white-space: nowrap !important;
}
div.chat-detail-screen:not(#_k) .input-reply-preview-name::before,
div.chat-detail-screen:not(#_k) .input-reply-preview-name::after {
  content: none !important;
  display: none !important;
}

/* 引用文字：一行，超长省略 */
div.chat-detail-screen:not(#_k) .input-reply-preview-text {
  flex: 1 1 auto !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  font-size: 13px !important;
  line-height: 18px !important;
  color: var(--rp-text-color) !important;
  -webkit-text-fill-color: var(--rp-text-color) !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}

/* --- 3. 缩略图不要 --- */
div.chat-detail-screen:not(#_k) .input-reply-preview-media {
  display: none !important;
}

/* --- 4. 关闭按钮：看不见，但点胶囊右侧仍可取消引用 --- */
div.chat-detail-screen:not(#_k) .input-reply-preview-close {
  position: absolute !important;
  right: 0 !important;
  top: 0 !important;
  bottom: 0 !important;
