  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  opacity: 0 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
}
/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【13b 预览条：头像 + 去掉「正在回复」+ 向下箭头】 ◆◆◆◆◆◆◆◆◆◆◆◆ */

:root {
  /* 🐕 */ --rp-avatar-size: 26px;      /* 头像大小 */
