/* --- 左侧滑块把手 (日夜适配 + 放大版双箭头) --- */
.input-btn-plus {
  width: 42px !important; 
  height: 42px !important; 
  min-width: 42px !important; 
  max-width: 42px !important;
  border-radius: 50% !important; 
  background: var(--slider-btn-bg, #ffffff) !important;
  border: var(--slider-btn-border, 1px solid rgba(0, 0, 0, 0.08)) !important;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.15) !important;
  display: flex !important; 
  align-items: center !important; 
  justify-content: center !important;
  margin-right: 8px !important; 
  transition: transform 0.15s ease !important; 
  z-index: 3 !important;
}
.input-btn-plus:active { transform: scale(0.92) translateX(4px); }
.input-btn-plus svg { display: none !important; }
.input-btn-plus::after {
  content: "" !important; 
