}

/* Slide to unlock 静态文案 */
.input-action-bar-custom:has(.input-box-custom:placeholder-shown)::after {
  content: "slide to unlock";
  position: absolute; 
  left: 8px; 
  top: 50%; 
  transform: translateY(-50%);
