  --voice-fake-time:"13\"";
  --voice-icon-size:19px;
  --voice-text-size:12px;
  --voice-me-icon-x:5px;
  --voice-me-icon-y:0px;
  --voice-me-text-x:6px;
  --voice-me-text-y:0px;
  --voice-them-icon-x:-4px;
  --voice-them-icon-y:0px;
