.chat-detail-screen .input-action-bar-custom:has(.input-box-custom:placeholder-shown) .input-btns-right::before {
  color: rgba(60, 60, 67, 0.45) !important;
}
.chat-detail-screen .input-btn-ai::before { background-color: var(--light-ink) !important; }
.chat-detail-screen .input-btn-plus {
