}

.footer-row {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  height: 15%;
}

.datetime-text {
  font-size: clamp(10px, 3.5cqw, 13px);
  font-weight: 400;
  color: var(--sub-text-color);
  opacity: 0.8;
  letter-spacing: 0.5px;
}

.mz-music-widget {
  width: 100%; height: 100%; position: relative;
  font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "PingFang SC", sans-serif;
  box-sizing: border-box; overflow: hidden;
  border-radius: 36px; 
  background-color: transparent; 
}

.glass-bg {
  position: absolute; top: 0; left: 0; 
  width: 100%; height: 100%; z-index: 1;
  backdrop-filter: blur(25px) saturate(180%);
  -webkit-backdrop-filter: blur(25px) saturate(180%);
  box-shadow: 
    inset 0 1px 0px var(--highlight-top), 
    inset 1px 1px 0px rgba(255, 255, 255, 0.04), 
    inset -1px 1px 0px rgba(255, 255, 255, 0.04),
    inset 1px 0px 0px rgba(255, 255, 255, 0.02),
    inset -1px 0px 0px rgba(255, 255, 255, 0.02),
    inset 0 -1px 0px var(--highlight-bottom);
}

.content-layer {
  position: relative; z-index: 3;
  display: flex; flex-direction: column; 
  height: 100%;
  padding: 12px 14px 12px 14px; 
  box-sizing: border-box;
}

/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ --- 1. 顶部栏 --- */
.top-row {
  display: flex; justify-content: space-between; align-items: flex-start;
}
.album-cover {
  width: 72px; height: 72px; 
  border-radius: 22px; 
  overflow: hidden;
  background-color: transparent;
  box-shadow: 0 6px 14px rgba(0,0,0,0.04); 
  margin-left: 6px; 
}
.album-cover img {
  width: 100%; height: 100%; object-fit: cover; display: block;
}

.cover-placeholder {
  width: 100%; height: 100%; 
  position: relative;
  display: none; align-items: center; justify-content: center;
  color: var(--icon-color);
  z-index: 1;
}
.cover-placeholder::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  background-color: var(--placeholder-bg-color);
  backdrop-filter: blur(20px) brightness(1.1) saturate(120%);
  -webkit-backdrop-filter: blur(20px) brightness(1.1) saturate(120%);
  z-index: -1;
}
.cover-placeholder svg { 
  width: 32px; height: 32px; 
  opacity: 0.9;
}

.cast-btn {
  width: 46px; height: 46px;
  display: flex; align-items: center; justify-content: center;
  color: var(--cast-icon-color);
  margin-top: 4px; 
  position: relative;
  z-index: 1;
}
.cast-btn::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0;
  border-radius: 50%;
  background-color: var(--cast-bg-color);
  backdrop-filter: blur(25px) brightness(1.06) saturate(120%);
  -webkit-backdrop-filter: blur(25px) brightness(1.06) saturate(120%);
  box-shadow: 
    inset 0 1px 0px rgba(255, 255, 255, 0.2),
    inset 0 0 0 1px rgba(255, 255, 255, 0.08);
  z-index: -1;
}
.cast-btn svg { 
  width: 26px; height: 26px; 
}

/* 🌟 === 中等/小尺寸适配 === 🌟 */
.mz-music-widget.size-medium .album-cover { width: 67px; height: 67px; border-radius: 20px; }
.mz-music-widget.size-medium .cover-placeholder svg { width: 30px; height: 30px; }
.mz-music-widget.size-medium .cast-btn { width: 42px; height: 42px; }
.mz-music-widget.size-medium .cast-btn svg { width: 24px; height: 24px; }

.mz-music-widget.size-small .album-cover { width: 62px; height: 62px; border-radius: 18px; }
.mz-music-widget.size-small .cover-placeholder svg { width: 28px; height: 28px; }
.mz-music-widget.size-small .cast-btn { width: 38px; height: 38px; }
.mz-music-widget.size-small .cast-btn svg { width: 22px; height: 22px; }

/* --- 2. 文本信息区 --- */
.text-row {
  display: flex; flex-direction: column; 
  gap: 0px; 
  margin-top: auto; 
  margin-bottom: 12px; 
  align-items: flex-start; 
  margin-left: 6px; 
}
.song-title {
  color: var(--song-color); font-size: var(--song-size); 
  font-weight: 500; 
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  max-width: 100%; 
  line-height: 1.15; 
}
.artist-name {
  color: var(--artist-color); font-size: var(--artist-size); 
  font-weight: 400;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  max-width: 100%;
  line-height: 1.15;
}

/* --- 3. 底部播放控制区 --- */
.controls-row {
  display: flex; justify-content: center; align-items: center; 
  gap: 8px; 
  margin-bottom: -4px; 
}
.ctrl-icon {
  color: var(--icon-color);
  display: flex; align-items: center; justify-content: center;
}

/* 🌟 去除了 prev-next 的独立透明度和混合模式，彻底与 play-btn 保持一致纯色 */

.play-btn svg { width: 36px; height: 30px; }
.prev-next svg { width: 52px; height: 30px; }

custom.css:
.page { position: absolute; inset: 0; color: #fff; font-family: -apple-system, "PingFang SC", sans-serif; }
.bg { position: absolute; inset: 0; background: {{accent}} url("{{portrait}}") center top / cover no-repeat; }
.bg::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,.4), rgba(0,0,0,0) 30%, rgba(0,0,0,0) 55%, rgba(0,0,0,.6)); }
.clock { position: absolute; left: 24px; top: calc(var(--safe-top, 44px) + 16px); }
.clock b { display: block; font-size: 64px; line-height: 1; letter-spacing: -1px; }
.clock small { display: block; margin-top: 6px; font-size: 14px; opacity: .9; }
.card { position: absolute; left: 20px; right: 20px; bottom: 124px; padding: 12px 16px; border-radius: 16px; background: rgba(255,255,255,.92); color: #333; }
.card em { font-style: normal; font-size: 13px; font-weight: 700; color: {{accent}}; }
.card p { margin: 4px 0 0; font-size: 15px; line-height: 1.5; }
.apps { position: absolute; left: 16px; right: 16px; bottom: 44px; display: flex; gap: 10px; }
.app { flex: 1; padding: 14px 0; border-radius: 16px; text-align: center; font-size: 13px; font-weight: 700; background: rgba(0,0,0,.35); border: 1px solid rgba(255,255,255,.35); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.app.start { background: {{accent}}; border-color: transparent; }
@keyframes rise { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
@keyframes shine { 0% { background-position: 150% 0; } 60%, 100% { background-position: -50% 0; } }
html.tp-fx:not(.tp-enter) .clock, html.tp-fx:not(.tp-enter) .card, html.tp-fx:not(.tp-enter) .apps { opacity: 0; }
.tp-enter .clock { animation: rise .8s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .card { animation: rise .8s .15s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .apps { animation: rise .8s .3s cubic-bezier(.2,.8,.2,1) both; }
.app.start { background-image: linear-gradient(110deg, transparent 35%, rgba(255,255,255,.55) 50%, transparent 65%); background-size: 250% 100%; background-repeat: no-repeat; animation: shine 3s ease-in-out infinite; }

