value.customCss:
.xt-root {
    --xt-bg: #ffffff;
    --xt-text: #1a1a1a;
    --xt-radius: 12px;
    --xt-radius-sm: 8px;
    padding: 6px;
    position: relative;
    background: var(--xt-bg);
    border: 2px solid #000;
    overflow-y: auto;
    overflow-x: hidden;
    max-height: 85vh;
}
.xt-root::-webkit-scrollbar { width: 6px; }
.xt-root::-webkit-scrollbar-track { background: #f0f0f0; }
.xt-root::-webkit-scrollbar-thumb { background: #333; border-radius: 3px; }

.xt-root > .xt-image:first-child {
    background: transparent !important;
    min-height: 100px !important;
    max-height: 150px !important;
    object-fit: contain !important;
    display: block !important;
}

.xt-row {
    display: flex !important;
    gap: 8px !important;
}
.xt-row > * {
    flex: 1 1 50% !important;
    max-width: 50% !important;
    min-width: 0 !important;
}
.xt-row .xt-image {
    background: transparent !important;
    height: 180px !important;
    max-height: 180px !important;
    min-height: 180px !important;
    width: 100% !important;
    object-fit: cover !important;
    border-radius: var(--xt-radius-sm);
    display: block !important;
}

/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ ===== 搜索和礼物：去掉竖线、灰底、边框 ===== */
.xt-card:has(.xt-text:contains("搜索")),
.xt-card:has(.xt-text:contains("🎂")) {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
}

/* 标题样式 */
.xt-card:has(.xt-text:contains("搜索")) .xt-text:first-child,
.xt-card:has(.xt-text:contains("🎂")) .xt-text:first-child {
    background: transparent !important;
    padding: 0 !important;
    margin-bottom: 4px !important;
    font-weight: 600;
    font-size: 13px;
    color: #222;
    letter-spacing: 1px;
    border: none !important;
    box-shadow: none !important;
}

/* 列表项：无边框无竖线 */
.xt-card:has(.xt-text:contains("搜索")) .xt-list-item,
.xt-card:has(.xt-text:contains("🎂")) .xt-list-item {
    border: none !important;
    padding: 4px 0 !important;
    font-size: 14px;
    color: #222;
    display: flex;
    align-items: flex-start;
    gap: 6px;
    line-height: 1.5;
    background: transparent !important;
    box-shadow: none !important;
}

/* ===== 搜索列表项前面强制加🔍 ===== */
.xt-card:has(.xt-text:contains("搜索")) .xt-list-item::before {
    content: "🔍" !important;
    font-size: 13px;
    color: #000;
    flex-shrink: 0;
}

/* 生日礼物前面加🎂 */
.xt-card:has(.xt-text:contains("🎂")) .xt-list-item::before {
    content: "🎂" !important;
    font-size: 13px;
    flex-shrink: 0;
}

/* ===== 待办事项：不带任何符号 ===== */
.xt-card:has(.xt-text:contains("TO-DO")) .xt-list-item::before {
    content: none !important;
}
.xt-card:has(.xt-text:contains("TO-DO")) .xt-list-item {
    padding: 4px 0 !important;
    border-bottom: 1px dashed #f0f0f0;
}
.xt-card:has(.xt-text:contains("TO-DO")) .xt-list-item:last-child {
    border-bottom: none;
}

.xt-list-item {
    padding: 4px 0 !important;
    color: #222;
    font-size: 14px;
    display: flex;
    align-items: center;
}
.xt-list-item:last-child {
    border-bottom: none;
}

.xt-card {
    background: #fff;
    border: 1px solid #ddd;
    padding: 12px !important;
    border-radius: var(--xt-radius);
    margin-bottom: 0 !important;
}
.xt-card:not(.img-pop) { box-shadow: 0 2px 8px rgba(0,0,0,0.05); }

.xt-card .xt-text {
    background: transparent !important;
    padding: 0 !important;
}

.xt-section-title {
    padding-left: 12px !important;
    font-weight: 600;
    font-size: 12px;
    color: #555;
    letter-spacing: 2px;
    margin-bottom: 4px;
    border-left: none !important;
}
.xt-section-body {
    padding: 4px 0 !important;
}

.xt-spacer {
    height: 4px !important;
}

.xt-bubbles { display: flex; flex-direction: column; gap: 6px; }
.xt-bubble { display: flex; flex-direction: column; max-width: 80%; }
.xt-bubble-left { align-items: flex-start; align-self: flex-start; }
.xt-bubble-right { align-items: flex-end; align-self: flex-end; }
.xt-bubble-left .xt-bubble-body { background: #e8e8e8; color: #222; border-radius: 14px 14px 14px 4px; padding: 6px 12px; font-size: 14px; }
.xt-bubble-right .xt-bubble-body { background: #1a1a1a; color: #f0f0f0; border-radius: 14px 14px 4px 14px; padding: 6px 12px; font-size: 14px; }

.xt-quote { border-left: 3px solid #222; padding: 8px 12px; line-height: 1.6; color: #333; background: #f8f8f8; border-radius: 0 8px 8px 0; font-style: italic; }
.xt-divider { border-top: 1px solid #eee; margin: 2px 0; }

.xt-row > div:nth-child(1) .xt-card:not(.img-pop) { border: 1px solid #79b8ff; background: #f6faff; }
.xt-row > div:nth-child(2) .xt-card:not(.img-pop) { border: 1px solid #ff7575; background: #fff6f6; }

.xt-footer { color: #999; margin-top: 12px; letter-spacing: 3px; font-size: 10px; border-top: 1px solid #eee; padding-top: 10px; text-align: center; }

