value.customCss:
/* ================= 基础重置 ================= */
.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { 
    margin: 0 !important; 
    padding: 0 !important; 
    border: none !important; 
    display: block !important; 
    box-shadow: none !important; 
    white-space: pre-wrap !important; 
    outline: none !important; 
    background: transparent !important; 
    border-radius: 0 !important; 
}

/* ================= 根容器 ================= */
.xt-root {
    width: 100% !important;
    max-width: 400px !important;
    height: 650px !important;
    background: transparent !important; 
    position: relative !important;
    margin: 0 auto !important;
    overflow: visible !important; 
    font-family: 'Times New Roman', Georgia, serif !important;
}

/* ================= 1-3. 缩小的侧边索引贴 ================= */
.xt-text:nth-of-type(1),
.xt-text:nth-of-type(2),
.xt-text:nth-of-type(3) {
    position: absolute !important;
    left: 4px !important;
    width: 20px !important;
    height: 60px !important;
    border-radius: 4px 0 0 4px !important;
    writing-mode: vertical-rl !important;
    text-orientation: mixed !important;
    text-align: center !important;
    padding-right: 6px !important;
    font-size: 8px !important;
    letter-spacing: 1px !important;
    color: #4a3f3f !important;
    box-shadow: -2px 2px 4px rgba(0,0,0,0.06) !important;
    z-index: 1 !important;
    font-family: Arial, Helvetica, sans-serif !important;
}
.xt-text:nth-of-type(1) { top: 70px !important; background-color: #c4d4c9 !important; } 
.xt-text:nth-of-type(2) { top: 150px !important; background-color: #c4d4ce !important; }
.xt-text:nth-of-type(3) { top: 230px !important; background-color: #c4cbd4 !important; }

/* ================= 4. 加宽的主体底板 ================= */
.xt-text:nth-of-type(4) {
    position: absolute !important;
    left: 20px !important;
    top: 20px !important;
    width: 340px !important;
    height: 610px !important;
    background-color: #fbfdfc !important; 
    border-radius: 2px !important;
    box-shadow: 8px 15px 30px rgba(0,0,0,0.08), 0 0 3px rgba(0,0,0,0.03) !important;
    z-index: 2 !important;
}
/* 档案编号 */
.xt-text:nth-of-type(4)::before {
    content: 'No. 7749-X' !important;
    position: absolute !important;
    top: 15px !important;
    right: 25px !important;
    font-family: 'Courier New', Courier, monospace !important;
    font-size: 10px !important;
    color: rgba(0,0,0,0.15) !important;
    letter-spacing: 1px !important;
}
/* 大型复古印章水印 */
.xt-text:nth-of-type(4)::after {
    content: ' MiMi\A xinsheng' !important;
    white-space: pre !important;
    text-align: center !important;
    position: absolute !important;
    top: 55% !important;
    left: 45% !important;
    transform: translate(-50%, -50%) rotate(-25deg) !important;
    font-size: 22px !important;
    line-height: 1.4 !important;
    color: rgba(120, 140, 125, 0.06) !important; 
    font-family: 'Courier New', Courier, monospace !important;
    font-weight: bold !important;
    letter-spacing: 2px !important;
    border: 4px double rgba(120, 140, 125, 0.06) !important;
    padding: 15px 20px !important;
    border-radius: 8px !important;
    pointer-events: none !important;
    z-index: 1 !important;
}

/* ================= 5. 右侧三角封口 (封头) ================= */
.xt-text:nth-of-type(5) {
    position: absolute !important;
    left: 190px !important; 
    top: 20px !important;
    width: 0 !important;
    height: 0 !important;
    border-top: 305px solid transparent !important;
    border-bottom: 305px solid transparent !important;
    border-right: 170px solid #eef7f1 !important; 
    filter: drop-shadow(-3px 0 3px rgba(0,0,0,0.03)) !important;
    z-index: 3 !important;
}

/* ================= 6. 复古邮戳 ================= */
.xt-text:nth-of-type(6) {
    position: absolute !important;
    left: 30px !important;
    top: 40px !important;
    width: 65px !important;
    height: 65px !important;
    border: 2px solid rgba(120, 140, 125, 0.4) !important;
    border-radius: 50% !important;
    color: rgba(120, 140, 125, 0.6) !important;
    font-size: 9px !important;
    text-align: center !important;
    line-height: 1.2 !important;
    padding-top: 17px !important;
    transform: rotate(-12deg) !important;
    z-index: 4 !important;
    font-family: 'Courier New', Courier, monospace !important;
}
.xt-text:nth-of-type(6)::before {
    content: '' !important; position: absolute !important;
    left: 5px !important; right: 5px !important; top: 22px !important; height: 1px !important;
    background: rgba(120, 140, 125, 0.3) !important;
}
.xt-text:nth-of-type(6)::after {
    content: '' !important; position: absolute !important;
    left: 5px !important; right: 5px !important; bottom: 22px !important; height: 1px !important;
    background: rgba(120, 140, 125, 0.3) !important;
}

/* ================= 7. 火漆印章 (自定义图片) ================= */
.xt-text:nth-of-type(7) {
    position: absolute !important;
    left: 200px !important; 
    top: 310px !important;  
    width: 30px !important;
    height: 30px !important;
    background-image: url('https://i.postimg.cc/44pfHwNJ/IMG-8187.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-color: transparent !important;
    z-index: 5 !important;
    color: transparent !important;
}

/* ================= 8. 顶部中间文案 1 ================= */
.xt-text:nth-of-type(8) {
    position: absolute !important;
    left: 115px !important;
    top: 50px !important;
    font-size: 10px !important;
    color: #999 !important;
    letter-spacing: 2px !important;
    font-family: 'Courier New', Courier, monospace !important;
    z-index: 4 !important;
    text-transform: uppercase !important;
}

/* ================= 9. 顶部中间文案 2 ================= */
.xt-text:nth-of-type(9) {
    position: absolute !important;
    left: 55px !important;
    top: 105px !important;
    font-size: 12px !important;
    color: #665c5c !important;
    font-style: italic !important;
    font-family: 'Times New Roman', Georgia, serif !important;
    z-index: 4 !important;
}

/* ================= 10. 左侧主标题 ================= */
.xt-text:nth-of-type(10) {
    position: absolute !important;
    left: 35px !important;
    top: 135px !important;
    width: 155px !important;
    font-size: 22px !important;
    color: #4a3f3f !important;
    font-style: italic !important;
    z-index: 4 !important;
}

/* ================= 11. 左侧副标题 ================= */
.xt-text:nth-of-type(11) {
    position: absolute !important;
    left: 45px !important;
    top: 170px !important;
    font-size: 9px !important;
    color: #888 !important;
    letter-spacing: 1.5px !important;
    z-index: 4 !important;
    font-family: Arial, Helvetica, sans-serif !important;
}

/* ================= 12. 左侧横线信纸排版正文 ================= */
.xt-text:nth-of-type(12) {
    position: absolute !important;
    left: 45px !important;
    top: 200px !important;
    width: 155px !important;
    height: 370px !important;
    font-size: 12px !important;
    line-height: 24px !important; 
    color: #554e4e !important;
    text-align: justify !important;
    overflow-y: auto !important;
    padding-right: 5px !important;
    z-index: 4 !important;
    background-image: repeating-linear-gradient(transparent, transparent 23px, rgba(0,0,0,0.06) 24px) !important;
    background-attachment: local !important;
}
.xt-text:nth-of-type(12)::-webkit-scrollbar { display: none !important; }

/* ================= 13. 右侧上方：便利贴 (支持滑动) ================= */
.xt-text:nth-of-type(13) {
    position: absolute !important;
    left: 200px !important;
    top: 80px !important;
    width: 140px !important;
    height: 130px !important;
    background-color: #fdfbf5 !important; 
    padding: 25px 12px 10px 12px !important; 
    font-size: 10px !important;
    line-height: 1.6 !important;
    color: #444 !important;
    box-shadow: 4px 6px 15px rgba(0,0,0,0.1) !important;
    transform: rotate(3deg) !important;
    z-index: 6 !important;
    font-family: 'Comic Sans MS', cursive, sans-serif !important; 
    overflow-y: auto !important; 
}
.xt-text:nth-of-type(13)::-webkit-scrollbar { display: none !important; } 

.xt-text:nth-of-type(13)::before {
    content: '' !important;
    position: absolute !important;
    top: 0px !important; 
    left: 50% !important;
    transform: translateX(-50%) rotate(-3deg) !important;
    width: 45px !important;
    height: 16px !important;
    background-color: rgba(255,255,255,0.7) !important;
    box-shadow: 0 1px 2px rgba(0,0,0,0.04) !important;
    border-left: 1px dashed rgba(0,0,0,0.1) !important;
    border-right: 1px dashed rgba(0,0,0,0.1) !important;
}

/* ================= 14. 右侧中间：拍立得照片 (纯白边框) ================= */
.xt-text:nth-of-type(14) {
    position: absolute !important;
    left: 205px !important;
    top: 240px !important;
    width: 145px !important;
    height: 165px !important;
    background-color: #ffffff !important; 
    box-shadow: 4px 8px 18px rgba(0,0,0,0.12) !important;
    transform: rotate(-4deg) !important;
    z-index: 7 !important;
    color: #555 !important;
    font-size: 10px !important;
    font-style: italic !important;
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
    display: flex !important;
    align-items: flex-end !important;
    justify-content: center !important;
    padding-bottom: 8px !important;
}
/* 照片图像本身 */
.xt-text:nth-of-type(14)::after {
    content: '' !important;
    position: absolute !important;
    top: 6px !important;
    left: 6px !important;
    right: 6px !important;
    height: 125px !important;
    background-image: url('https://i.postimg.cc/9fQcqjgc/IMG-8207.jpg') !important;
    background-size: cover !important;
    background-position: center !important;
    z-index: 1 !important;
}
/* 照片上的回形针装饰 */
.xt-text:nth-of-type(14)::before {
    content: '' !important; 
    position: absolute !important;
    top: -12px !important; 
    left: 20px !important;
    width: 12px !important; 
    height: 35px !important;
    border: 2px solid #a0a0a0 !important;
    border-radius: 6px !important;
    box-shadow: 1px 2px 3px rgba(0,0,0,0.2) !important;
    z-index: 8 !important;
}

/* ================= 15. 右侧下方：附加文字区 ================= */
.xt-text:nth-of-type(15) {
    position: absolute !important;
    left: 205px !important; 
    top: 420px !important;
    width: 140px !important; 
    height: 150px !important;
    font-size: 11px !important;
    line-height: 1.7 !important;
    color: #8c7e7e !important;
    font-style: italic !important;
    z-index: 4 !important;
    overflow-y: auto !important;
    padding-top: 20px !important; 
}
.xt-text:nth-of-type(15)::-webkit-scrollbar { display: none !important; }

.xt-text:nth-of-type(15)::before {
    content: '“' !important;
    position: absolute !important;
    left: 0px !important;
    top: -10px !important;
    font-size: 50px !important;
    color: rgba(120, 140, 125, 0.15) !important;
    font-family: Georgia, serif !important;
    pointer-events: none !important;
}

/* ================= 16. 左下角：装饰标签 ================= */
.xt-text:nth-of-type(16) {
    position: absolute !important;
    left: 45px !important;
    bottom: 30px !important;
    background-color: #4a3f3f !important;
    color: #ffffff !important;
    padding: 4px 10px !important;
    font-size: 9px !important;
    letter-spacing: 2px !important;
    z-index: 5 !important;
    font-family: Arial, Helvetica, sans-serif !important;
    border-radius: 2px !important;
}

